window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d7cce427d2068ba8"]={"versions": [{"id": "FIG-d7cce427d2068ba8", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell des AUTOSAR-FlexRay-Transceiver-Treibers (FrTrcv Driver) innerhalb des Kommunikationsstacks der AUTOSAR Classic Platform. Das Blockdiagramm veranschaulicht die hierarchische Einordnung und Multi-Vendor- bzw. Multi-Transceiver-Fähigkeit zwischen dem softwarebasierten FlexRay Interface (FrIf) auf der oberen Ebene, den herstellerspezifischen Transceiver-Treibern (Software) und den darunterliegenden physikalischen Transceiver-Hardwarebausteinen sowie dem physikalischen FlexRay-Busmedium. Rechts kennzeichnen vertikale Balken die Schichtenzuordnung (&quot;Soft...&quot; / Software bzw. &quot;Hard...&quot; / Hardware).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in zwei Hauptdomänen sowie ein physikalisches Medium:</p>\n<ul class=\"fig-list\"><li><strong>Software-Ebene (oben):</strong>\n<ul class=\"fig-list\"><li><strong>FlexRay Interface:</strong> Übergreifendes Softwaremodul, das als einheitliche Schnittstelle oberhalb der Transceiver-Treiber fungiert.\n</li><li><strong>FrTrcv Driver:</strong> Drei parallele Treibermodule unterschiedlicher Hersteller:\n<ul class=\"fig-list\"><li><code>FrTrcv Driver Vendor A</code>\n</li><li><code>FrTrcv Driver Vendor B</code>\n</li><li><code>FrTrcv Driver Vendor C</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Hardware-Ebene (Mitte):</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Vendor A</code>: Zwei separate Hardware-Instanzen des Typs <code>Trcv Type X</code>.\n</li><li>Unterhalb von <code>Vendor B</code>: Eine einzelne Hardware-Instanz des Typs <code>Trcv Type Y</code>.\n</li><li>Unterhalb von <code>Vendor C</code>: Zwei aneinandergrenzende/kombinierte Hardware-Instanzen des Typs <code>Trcv Type Z</code> (z. B. Dual-Channel-Transceiver oder getrennte Kanäle).\n</li></ul>\n</li><li><strong>Physikalisches Übertragungsmedium (unten):</strong>\n<ul class=\"fig-list\"><li>Horizontaler Block <code>FlexRay physical medium</code>, an den die Transceiver-Hardwarebausteine physikalisch angebunden sind.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichten- und Komponentenarchitektur ohne dynamische Ablauf- oder Sequenzpfade. Aus der Topologie geht hervor, dass das FlexRay Interface Funktionsaufrufe an unterschiedliche herstellerspezifische FrTrcv-Treiber weiterleitet (1:n-Beziehung). Jeder Treiber steuert eine oder mehrere Hardware-Transceiver-Einheiten gleicher Bauart an (Vendor A bedient zwei Transceiver vom Typ X; Vendor B bedient einen Transceiver vom Typ Y; Vendor C bedient zwei Einheiten vom Typ Z), welche ihrerseits die Schnittstelle zum physikalischen FlexRay-Busmedium bilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Architekturdiagramm veranschaulicht die Konfigurationsflexibilität des AUTOSAR FrTrcv-Treibers:</p>\n<ul class=\"fig-list\"><li><strong>Multi-Vendor-Unterstützung:</strong> Ein Steuergerät (ECU) kann gleichzeitig FlexRay-Transceiver-Treiber unterschiedlicher Hersteller einbinden.\n</li><li><strong>Multi-Channel / Multi-Instance:</strong> Ein einzelner FrTrcv-Treiber kann mehrere Hardware-Transceiver desselben Typs ansteuern (z. B. 2x Type X durch Vendor A oder 2x Type Z durch Vendor C).\n</li><li><strong>Abstraktion:</strong> Das FlexRay Interface kapselt herstellerspezifische Implementierungen gegenüber höheren Kommunikationsschichten.\n</li></ul>"}, {"id": "FIG-724ab2aacdb568a6", "releases": ["R3.0.7", "R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell des AUTOSAR-FlexRay-Transceiver-Treibers (FrTrcv Driver) innerhalb des Kommunikationsstacks der AUTOSAR Classic Platform. Das Blockdiagramm veranschaulicht die hierarchische Einordnung und Multi-Vendor- bzw. Multi-Transceiver-Fähigkeit zwischen dem softwarebasierten FlexRay Interface (FrIf) auf der oberen Ebene, den herstellerspezifischen Transceiver-Treibern (Software) und den darunterliegenden physikalischen Transceiver-Hardwarebausteinen sowie dem physikalischen FlexRay-Busmedium. Rechts kennzeichnen vertikale Balken vollständig lesbar die Schichtenzuordnung (&quot;Software&quot; bzw. &quot;Hardware&quot;).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in zwei Hauptdomänen sowie ein physikalisches Medium:</p>\n<ul class=\"fig-list\"><li><strong>Software-Ebene (oben):</strong>\n<ul class=\"fig-list\"><li><strong>FlexRay Interface:</strong> Übergreifendes Softwaremodul, das als einheitliche Schnittstelle oberhalb der Transceiver-Treiber fungiert.\n</li><li><strong>FrTrcv Driver:</strong> Drei parallele Treibermodule unterschiedlicher Hersteller:\n<ul class=\"fig-list\"><li><code>FrTrcv Driver Vendor A</code>\n</li><li><code>FrTrcv Driver Vendor B</code>\n</li><li><code>FrTrcv Driver Vendor C</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Hardware-Ebene (Mitte):</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Vendor A</code>: Zwei separate Hardware-Instanzen des Typs <code>Trcv Type X</code>.\n</li><li>Unterhalb von <code>Vendor B</code>: Eine einzelne Hardware-Instanz des Typs <code>Trcv Type Y</code>.\n</li><li>Unterhalb von <code>Vendor C</code>: Zwei aneinandergrenzende/kombinierte Hardware-Instanzen des Typs <code>Trcv Type Z</code> (z. B. Dual-Channel-Transceiver oder getrennte Kanäle).\n</li></ul>\n</li><li><strong>Physikalisches Übertragungsmedium (unten):</strong>\n<ul class=\"fig-list\"><li>Horizontaler Block <code>FlexRay physical medium</code>, an den die Transceiver-Hardwarebausteine physikalisch angebunden sind.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichten- und Komponentenarchitektur ohne dynamische Ablauf- oder Sequenzpfade. Aus der Topologie geht hervor, dass das FlexRay Interface Funktionsaufrufe an unterschiedliche herstellerspezifische FrTrcv-Treiber weiterleitet (1:n-Beziehung). Jeder Treiber steuert eine oder mehrere Hardware-Transceiver-Einheiten gleicher Bauart an (Vendor A bedient zwei Transceiver vom Typ X; Vendor B bedient einen Transceiver vom Typ Y; Vendor C bedient zwei Einheiten vom Typ Z), welche ihrerseits die Schnittstelle zum physikalischen FlexRay-Busmedium bilden.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Architekturdiagramm veranschaulicht die Konfigurationsflexibilität des AUTOSAR FrTrcv-Treibers:</p>\n<ul class=\"fig-list\"><li><strong>Multi-Vendor-Unterstützung:</strong> Ein Steuergerät (ECU) kann gleichzeitig FlexRay-Transceiver-Treiber unterschiedlicher Hersteller einbinden.\n</li><li><strong>Multi-Channel / Multi-Instance:</strong> Ein einzelner FrTrcv-Treiber kann mehrere Hardware-Transceiver desselben Typs ansteuern (z. B. 2x Type X durch Vendor A oder 2x Type Z durch Vendor C).\n</li><li><strong>Abstraktion:</strong> Das FlexRay Interface kapselt herstellerspezifische Implementierungen gegenüber höheren Kommunikationsschichten.\n</li></ul>"}, {"id": "FIG-741ab186ef8fb852", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Architektur- und Schichtenmodell des AUTOSAR-FlexRay-Transceiver-Treibers (FrTrcv Driver) innerhalb des Kommunikationsstacks der AUTOSAR Classic Platform. Das Blockdiagramm veranschaulicht die hierarchische Einordnung und Multi-Vendor- bzw. Multi-Transceiver-Fähigkeit zwischen dem softwarebasierten FlexRay Interface (FrIf) auf der oberen Ebene, den herstellerspezifischen Transceiver-Treibern (Software) und den darunterliegenden physikalischen Transceiver-Hardwarebausteinen. Rechts kennzeichnen vertikale Balken die Schichtenzuordnung (&quot;Soft...&quot; / Software bzw. &quot;Hard...&quot; / Hardware).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich vertikal in zwei Hauptdomänen:</p>\n<ul class=\"fig-list\"><li><strong>Software-Ebene (oben):</strong>\n<ul class=\"fig-list\"><li><strong>FlexRay Interface:</strong> Übergreifendes Softwaremodul, das als einheitliche Schnittstelle oberhalb der Transceiver-Treiber fungiert.\n</li><li><strong>FrTrcv Driver:</strong> Drei parallele Treibermodule unterschiedlicher Hersteller:\n<ul class=\"fig-list\"><li><code>FrTrcv Driver Vendor A</code>\n</li><li><code>FrTrcv Driver Vendor B</code>\n</li><li><code>FrTrcv Driver Vendor C</code>\n</li></ul>\n</li></ul>\n</li><li><strong>Hardware-Ebene (unten):</strong>\n<ul class=\"fig-list\"><li>Unterhalb von <code>Vendor A</code>: Zwei separate Hardware-Instanzen des Typs <code>Trcv Type X</code>.\n</li><li>Unterhalb von <code>Vendor B</code>: Eine einzelne Hardware-Instanz des Typs <code>Trcv Type Y</code>.\n</li><li>Unterhalb von <code>Vendor C</code>: Zwei aneinandergrenzende/kombinierte Hardware-Instanzen des Typs <code>Trcv Type Z</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Schichten- und Komponentenarchitektur ohne dynamische Ablauf- oder Sequenzpfade. Aus der Topologie geht hervor, dass das FlexRay Interface Funktionsaufrufe an unterschiedliche herstellerspezifische FrTrcv-Treiber weiterleitet (1:n-Beziehung). Jeder Treiber steuert eine oder mehrere Hardware-Transceiver-Einheiten gleicher Bauart an (Vendor A bedient zwei Transceiver vom Typ X; Vendor B bedient einen Transceiver vom Typ Y; Vendor C bedient zwei Einheiten vom Typ Z).</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Architekturdiagramm veranschaulicht die Konfigurationsflexibilität des AUTOSAR FrTrcv-Treibers:</p>\n<ul class=\"fig-list\"><li><strong>Multi-Vendor-Unterstützung:</strong> Ein Steuergerät (ECU) kann gleichzeitig FlexRay-Transceiver-Treiber unterschiedlicher Hersteller einbinden.\n</li><li><strong>Multi-Channel / Multi-Instance:</strong> Ein einzelner FrTrcv-Treiber kann mehrere Hardware-Transceiver desselben Typs ansteuern (z. B. 2x Type X durch Vendor A oder 2x Type Z durch Vendor C).\n</li><li><strong>Abstraktion:</strong> Das FlexRay Interface kapselt herstellerspezifische Implementierungen gegenüber höheren Kommunikationsschichten.\n</li></ul>"}], "trans": [{"from": "FIG-d7cce427d2068ba8", "to": "FIG-724ab2aacdb568a6", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Beschriftung am rechten Randbalken für Hardware: Der Text &quot;Hardware&quot; ist nun vollständig sichtbar und nicht mehr am rechten Rand abgeschnitten.\n</li><li>Beschriftung am rechten Randbalken für Software: Der Text &quot;Software&quot; ist nun vollständig sichtbar und nicht mehr am rechten Rand abgeschnitten.\n</li></ul>"}, {"from": "FIG-724ab2aacdb568a6", "to": "FIG-741ab186ef8fb852", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Untere Komponente: Die Leiste &quot;FlexRay physical medium&quot; am unteren Bildrand wurde entfernt.\n</li><li>Beschriftung am rechten Randbalken für Hardware: Der Text &quot;Hardware&quot; ist am rechten Rand wieder teilweise abgeschnitten (&quot;Hard&quot;).\n</li><li>Beschriftung am rechten Randbalken für Software: Der Text &quot;Software&quot; ist am rechten Rand wieder teilweise abgeschnitten (&quot;Soft&quot;).\n</li></ul>"}]};
